class_name World
extends RefCounted

var title: String = ""
var start_room_id: String = ""
var rooms: Dictionary = {}
var last_error: String = ""


func load_file(file_path: String) -> bool:
	last_error = ""
	rooms.clear()
	title = ""
	start_room_id = ""

	if not FileAccess.file_exists(file_path):
		_fail("Il file '%s' non esiste." % file_path)
		return false

	var file := FileAccess.open(file_path, FileAccess.READ)
	if file == null:
		_fail("Impossibile aprire il file '%s'." % file_path)
		return false

	var content := file.get_as_text()
	file.close()

	var parsed = JSON.parse_string(content)
	if not (parsed is Dictionary):
		_fail("Il file '%s' non contiene un oggetto JSON valido." % file_path)
		return false

	var data: Dictionary = parsed
	if not data.has("title") or not (data["title"] is String):
		_fail("Campo obbligatorio 'title' mancante o non valido.")
		return false
	if not data.has("start_room") or not (data["start_room"] is String):
		_fail("Campo obbligatorio 'start_room' mancante o non valido.")
		return false
	if not data.has("rooms") or not (data["rooms"] is Dictionary):
		_fail("Campo obbligatorio 'rooms' mancante o non valido.")
		return false

	var raw_rooms: Dictionary = data["rooms"]
	var target_start: String = data["start_room"]
	if not raw_rooms.has(target_start):
		_fail("La stanza iniziale '%s' non esiste nel dizionario 'rooms'." % target_start)
		return false

	# Prima passata: validazione difensiva di tutte le stanze e dei loro collegamenti
	for room_id in raw_rooms:
		var r_data = raw_rooms[room_id]
		if not (r_data is Dictionary):
			_fail("I dati della stanza '%s' devono essere un Dictionary." % str(room_id))
			return false
		var r_dict: Dictionary = r_data
		if not r_dict.has("name") or not (r_dict["name"] is String):
			_fail("La stanza '%s' non ha un campo 'name' di tipo String." % str(room_id))
			return false
		if not r_dict.has("description") or not (r_dict["description"] is String):
			_fail("La stanza '%s' non ha un campo 'description' di tipo String." % str(room_id))
			return false
		if not r_dict.has("exits") or not (r_dict["exits"] is Dictionary):
			_fail("La stanza '%s' non ha un campo 'exits' di tipo Dictionary." % str(room_id))
			return false
		if not r_dict.has("items") or not (r_dict["items"] is Array):
			_fail("La stanza '%s' non ha un campo 'items' di tipo Array." % str(room_id))
			return false
		if r_dict.has("locked_exits") and not (r_dict["locked_exits"] is Dictionary):
			_fail("Il campo 'locked_exits' della stanza '%s' deve essere un Dictionary." % str(room_id))
			return false
		if r_dict.has("is_end") and not (r_dict["is_end"] is bool):
			_fail("Il campo 'is_end' della stanza '%s' deve essere un bool." % str(room_id))
			return false

		var exits: Dictionary = r_dict["exits"]
		for dir in exits:
			var destination = exits[dir]
			if not (destination is String) or not raw_rooms.has(destination):
				_fail("L'uscita '%s' della stanza '%s' punta a '%s', che non esiste." % [str(dir), str(room_id), str(destination)])
				return false

	# Seconda passata: instanziazione degli oggetti Room solo a validazione completata
	title = data["title"]
	start_room_id = target_start

	for room_id in raw_rooms:
		var r_dict: Dictionary = raw_rooms[room_id]
		var room := Room.new()
		room.id = str(room_id)
		room.name = r_dict["name"]
		room.description = r_dict["description"]
		room.exits = r_dict["exits"].duplicate()
		var items_list: Array[String] = []
		for item in r_dict["items"]:
			items_list.append(str(item))
		room.items = items_list
		room.locked_exits = r_dict.get("locked_exits", {}).duplicate()
		room.is_end = r_dict.get("is_end", false)
		rooms[room.id] = room

	return true


func get_room(room_id: String) -> Room:
	if rooms.has(room_id):
		return rooms[room_id] as Room
	return null


func get_start_room() -> Room:
	return get_room(start_room_id)


func _fail(message: String) -> void:
	last_error = message
	push_error(message)

extends Control

var world: World
var current_room: Room
var inventory: Array[String] = []

@onready var room_title: Label = $MarginContainer/VBoxContainer/RoomTitle
@onready var room_description: Label = $MarginContainer/VBoxContainer/RoomDescription
@onready var exits_container: HBoxContainer = $MarginContainer/VBoxContainer/ExitsContainer
@onready var items_container: HBoxContainer = $MarginContainer/VBoxContainer/ItemsContainer
@onready var inventory_label: Label = $MarginContainer/VBoxContainer/InventoryLabel
@onready var message_label: Label = $MarginContainer/VBoxContainer/MessageLabel


func _ready() -> void:
	world = World.new()
	var success := world.load_file("res://adventure.json")
	if not success:
		message_label.text = "Errore nel caricamento: %s" % world.last_error
		return

	current_room = world.get_start_room()
	_update_inventory_ui()
	_update_room_ui()


func _update_room_ui() -> void:
	if current_room == null:
		return

	room_title.text = current_room.name
	room_description.text = current_room.description

	# Svuota i pulsanti precedenti
	for child in exits_container.get_children():
		exits_container.remove_child(child)
		child.queue_free()

	for child in items_container.get_children():
		items_container.remove_child(child)
		child.queue_free()

	# Se la stanza e terminale, mostra la vittoria e non crea uscite
	if current_room.is_end:
		message_label.text = "Complimenti! Hai raggiunto la fine dell'avventura!"
		return

	# Crea un pulsante per ogni uscita disponibile
	for dir in current_room.exits:
		var btn := Button.new()
		btn.text = dir
		btn.pressed.connect(_on_exit_pressed.bind(dir))
		exits_container.add_child(btn)

	# Crea un pulsante per ogni oggetto presente nella stanza
	for item in current_room.items:
		var btn := Button.new()
		btn.text = item
		btn.pressed.connect(_on_item_pressed.bind(item))
		items_container.add_child(btn)


func _update_inventory_ui() -> void:
	if inventory.is_empty():
		inventory_label.text = "Inventario: (vuoto)"
	else:
		var text := "Inventario: "
		for i in range(inventory.size()):
			text += inventory[i]
			if i < inventory.size() - 1:
				text += ", "
		inventory_label.text = text


func _on_exit_pressed(dir: String) -> void:
	if current_room == null:
		return

	# Controllo uscita bloccata
	if current_room.locked_exits.has(dir):
		var required_item: String = current_room.locked_exits[dir]
		if not inventory.has(required_item):
			message_label.text = "L'uscita verso '%s' e bloccata! Ti serve: %s." % [dir, required_item]
			return

	var next_id: String = current_room.exits.get(dir, "")
	var next_room := world.get_room(next_id)
	if next_room != null:
		current_room = next_room
		message_label.text = ""
		_update_room_ui()


func _on_item_pressed(item: String) -> void:
	if current_room == null:
		return

	if current_room.items.has(item):
		current_room.items.erase(item)
		inventory.append(item)
		message_label.text = "Hai raccolto: %s." % item
		_update_inventory_ui()
		_update_room_ui()
